META = dict(
    outline='சுலோகங்கள் 1–3: இருபத்தாறு தெய்வீக குணங்கள்; 4–5: அசுர குணங்கள், இரண்டும் எங்கே கொண்டுசெல்கின்றன; 6–18: அசுர இயல்பினர் எப்படிச் சிந்திக்கிறார்கள், நடந்துகொள்கிறார்கள்; 19–20: அவர்களுக்கு என்ன ஆகிறது; 21–22: காமம், கோபம், பேராசை: நரகத்தின் மூன்று வாயில்கள்; 23–24: எதைச் செய்ய வேண்டும் என்பதற்கு சாஸ்திரமே வழிகாட்டி.',
)
T = {
2: 'அகிம்சை, உண்மை, கோபமின்மை, தியாகம், அமைதி, புறங்கூறாமை, எல்லா உயிர்களிடமும் கருணை, பேராசையின்மை, மென்மை, நாணம், சஞ்சலமின்மை,',
3: 'ஒளி, பொறுமை, தைரியம், தூய்மை, யாரிடமும் பகையின்மை, கர்வமின்மை: பாரதா, இவை தெய்வீகச் செல்வத்துடன் பிறந்தவனின் குணங்கள்.',
4: 'பார்த்தா, போலித்தனம், ஆணவம், தற்பெருமை, கோபம், கடுமை, அறியாமை: இவை அசுரச் செல்வத்துடன் பிறந்தவனின் அடையாளங்கள்.',
5: 'தெய்வீகச் செல்வம் விடுதலைக்கும், அசுரச் செல்வம் கட்டுக்கும் வழிவகுக்கும் என்று கருதப்படுகிறது. பாண்டவா, வருந்தாதே, நீ தெய்வீகச் செல்வத்துடன் பிறந்தவன்.',
6: 'பார்த்தா, இந்த உலகில் இரண்டு வகை உயிர்கள் உள்ளன: தெய்வீகமானவை, அசுரமானவை. தெய்வீகமானது விரிவாகச் சொல்லப்பட்டது; இப்போது அசுரமானதைப் பற்றி என்னிடம் கேள்.',
7: 'அசுர இயல்பினர் எதைச் செய்ய வேண்டும் என்றும் அறியார், எதைச் செய்யக்கூடாது என்றும் அறியார். அவர்களிடம் தூய்மையும் இல்லை, நல்லொழுக்கமும் இல்லை, உண்மையும் இல்லை.',
8: 'இந்த உலகம் பொய்யானது, ஆதாரமற்றது, இறைவன் இல்லாதது என்று அவர்கள் சொல்கிறார்கள். ஆண் பெண் சேர்க்கையால் மட்டுமே தோன்றியது; காமத்தைத் தவிர வேறு காரணம் என்ன என்கிறார்கள்.',
9: 'இந்தக் கருத்தைப் பற்றிக்கொண்டு, ஆத்மாவை இழந்த, அற்ப அறிவுடைய, கொடிய செயல் செய்பவர்கள் உலகின் பகைவர்களாகி அதை அழிக்க எழுகிறார்கள்.',
10: 'என்றும் நிறைவடையாத ஆசைகளைச் சார்ந்து, போலித்தனமும் கர்வமும் ஆணவமும் நிறைந்து, மயக்கத்தால் தவறான கருத்துகளைப் பற்றிக்கொண்டு, அவர்கள் தூய்மையற்ற நோக்கங்களுடன் செயல்படுகிறார்கள்.',
11: 'மரணம் வரை நீடிக்கும் அளவற்ற கவலைகளில் மூழ்கி, ஆசைகளை அனுபவிப்பதையே உயர்ந்த இலக்காகக் கொண்டு, இவ்வளவுதான் எல்லாம் என்று உறுதியாக நம்புகிறார்கள்.',
12: 'நூற்றுக்கணக்கான ஆசைக் கயிறுகளால் கட்டுண்டு, காமமும் கோபமும் நிறைந்து, ஆசைகளை அனுபவிப்பதற்காக அநியாய வழியில் செல்வம் சேர்க்க முயல்கிறார்கள்.',
13: '"இன்று இதை அடைந்தேன், அடுத்து இந்த ஆசையை நிறைவேற்றுவேன். இது என்னுடையது, இந்தச் செல்வமும் இனி என்னுடையதாகும்."',
14: '"அந்தப் பகைவனைக் கொன்றேன், மற்றவர்களையும் கொல்வேன். நானே இறைவன், நானே அனுபவிப்பவன், நான் வெற்றியாளன், வலிமையானவன், மகிழ்ச்சியானவன்."',
15: '"நான் செல்வந்தன், உயர் குலத்தவன்; எனக்கு நிகர் யார்? யாகம் செய்வேன், தானம் தருவேன், கொண்டாடுவேன்." இவ்வாறு அவர்கள் அறியாமையால் மயங்குகிறார்கள்.',
16: 'பல எண்ணங்களால் குழம்பி, மயக்க வலையில் சிக்கி, ஆசைகளை அனுபவிப்பதில் மூழ்கி, அவர்கள் அசுத்தமான நரகத்தில் விழுகிறார்கள்.',
17: 'தங்களையே பெரிதாக நினைப்பவர்கள், பிடிவாதமானவர்கள், செல்வத்தாலும் மானத்தாலும் போதையுற்றவர்கள், காட்சிக்காக, முறையின்றி, பெயரளவுக்கு மட்டுமே யாகம் செய்கிறார்கள்.',
18: 'அகங்காரம், பலம், ஆணவம், காமம், கோபம் ஆகியவற்றைச் சார்ந்து, பொறாமை கொண்ட இவர்கள், தங்கள் உடலிலும் பிறர் உடலிலும் இருக்கும் என்னை வெறுக்கிறார்கள்.',
19: 'வெறுப்பு நிறைந்த, கொடிய, தீய, மனிதர்களில் கீழான அவர்களை நான் சம்சாரத்தில் மீண்டும் மீண்டும் அசுரப் பிறவிகளிலேயே தள்ளுகிறேன்.',
20: 'கௌந்தேயா, அசுரப் பிறவிகளில் விழுந்த அந்த மூடர்கள், பிறவிதோறும் என்னை அடையாமல், அதை விடவும் தாழ்ந்த நிலைக்குச் செல்கிறார்கள்.',
22: 'கௌந்தேயா, இருளின் இந்த மூன்று வாயில்களிலிருந்தும் விடுபட்டவன் தன் ஆத்மாவுக்கு நன்மை தருவதைச் செய்கிறான்; அதனால் பரம கதியை அடைகிறான்.',
23: 'சாஸ்திர விதியை விட்டு, ஆசையின் உந்துதலால் மனம் போனபடி நடப்பவன், சித்தியையும் அடைவதில்லை, இன்பத்தையும் அடைவதில்லை, பரம கதியையும் அடைவதில்லை.',
24: 'எனவே எதைச் செய்ய வேண்டும், எதைச் செய்யக்கூடாது என்பதைத் தீர்மானிப்பதில் சாஸ்திரமே உனக்கு வழிகாட்டி. சாஸ்திரம் சொல்வதை அறிந்து இவ்வுலகில் உன் கடமையைச் செய்.',
}
